// src/themes/terrain/pixel/types.ts
init_cjs_shims();
var PIXEL_GRID_STEP = 0.5;

// src/themes/terrain/pixel/render.ts
var MissingPixelSpriteError = class extends Error {
  constructor(catalogId) {
    super(`Missing compiled pixel sprite ${catalogId}; run npx tsx scripts/pixel/generate.ts`);
    this.catalogId = catalogId;
    this.name = "MissingPixelSpriteError";
  }
};
function renderPixelAsset(id, x, y, colors, variant = 0) {
  if (!Object.hasOwn(PIXEL_SPRITES, id)) throw new MissingPixelSpriteError(id);
  const variants = PIXEL_SPRITES[id];
  if (!variants?.length) throw new MissingPixelSpriteError(id);
  const selected = Number.isFinite(variant) ? Math.trunc(variant) : 0;
  const index = (selected % variants.length + variants.length) % variants.length;
  const sprite = variants[index];
  const paths = sprite.layers.map(({ paint, d }) => `<path fill="${escapeXml(resolvePixelPaint(paint, colors))}" d="${d}"/>`).join("");
  return `<g data-art-style="pixel" data-pixel-grid="${PIXEL_GRID_STEP}" shape-rendering="crispEdges" transform="translate(${x},${y})">${paths}</g>`;
}

// src/themes/terrain/epics/rendering.ts
function renderEpicGlowDefs(mode) {
  const tiers = [
    { id: "epic-glow-rare", color: "#FFD700", darkOuter: 0, lightOuter: 0 },
    { id: "epic-glow-epic", color: "#9B59B6", darkOuter: 0, lightOuter: 0 },
    { id: "epic-glow-legendary", color: "#00CED1", darkOuter: 0, lightOuter: 0 }
  ];
  return tiers.map(
    (t) => `<radialGradient id="${motionId(t.id)}"><stop offset="0%" stop-color="${t.color}" stop-opacity="${mode === "dark" ? 0.4 : 0.3}"/><stop offset="100%" stop-color="${t.color}" stop-opacity="0"/></radialGradient>`
  ).join("");
}
function renderEpicCSS() {
  return motionMarkup(
    [
      `@keyframes epic-pulse { 0%,100% { opacity: 0.4; } 50% { opacity: 0.9; } }`,
      `.epic-glow-pulse { animation: epic-pulse 3s ease-in-out infinite; }`,
      `@keyframes epic-swirl { 0% { transform: rotate(0deg); } 100% { transform: rotate(360deg); } }`,
      `.epic-portal-swirl { animation: epic-swirl 8s linear infinite; transform-origin: center; }`
    ].join("\n")
  );
}
function renderEpicBuildings(placed, weekPalettes, artStyle = "miniature") {
  if (placed.length === 0) return "";
  const parts = placed.map((epic) => {
    const weekIdx = Math.min(epic.week, weekPalettes.length - 1);
    const palette = weekPalettes[weekIdx];
    const c = palette.assets;
    const renderer = EPIC_RENDERERS[epic.type];
    const glowId = `epic-glow-${epic.tier}`;
    const glow = artStyle === "pixel" ? "" : `<ellipse cx="${epic.cx}" cy="${epic.cy}" rx="8" ry="4" fill="url(#${motionId(glowId)})" opacity="0.6"/>`;
    const building = artStyle === "pixel" ? renderPixelAsset(epic.type, epic.cx, epic.cy, c) : renderer(epic.cx, epic.cy, c);
    return `<g data-catalog-id="${epic.type}" data-date="${escapeXml(epic.date ?? "")}" data-wonder-id="${escapeXml(epic.id ?? `wonder:${epic.week},${epic.day}`)}">${glow}${building}</g>`;
  });
  return `<g class="epic-buildings">${parts.join("")}</g>`;
}

